# چاپ اعداد ۰ تا ۴
for i in range(5):
    print(i)

# چاپ اعداد ۱ تا ۵
for i in range(1, 6):
    print(i)

# break
for i in range(10):
    if i == 5:
        break
    print(i)

# continue
for i in range(5):
    if i == 2:
        continue
    print(i)

